  members_releaseMessage: 'ಈ ಹೆಸರಿನಲ್ಲಿ ಸೇರಿದವರು ಗುಂಪಿನಿಂದ ಹೊರಹೋಗುತ್ತಾರೆ: {name}. ಹೆಸರು {name}, ಅದರ ಬಣ್ಣ ಮತ್ತು ಖರ್ಚುಗಳು ಹಾಗೆಯೇ ಇರುತ್ತವೆ, ಮತ್ತು ಗುಂಪಿನ ಲಿಂಕ್ ಮೂಲಕ ಈ ಹೆಸರನ್ನು ಮತ್ತೆ ಆಯ್ಕೆಮಾಡಬಹುದು: {name}.',
  members_releaseConfirm: 'ಬಿಡುಗಡೆ ಮಾಡಿ',
  members_releaseError: 'ಹೆಸರನ್ನು ಬಿಡುಗಡೆ ಮಾಡಲು ಆಗಲಿಲ್ಲ. ನಿಮ್ಮ ಸಂಪರ್ಕ ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  members_add: 'ವ್ಯಕ್ತಿಯನ್ನು ಸೇರಿಸಿ',
