  members_personalMessage: 'ಈ ಲಿಂಕ್ ತೆರೆಯುವವರು ಪಟ್ಟಿಯಿಂದ ಆಯ್ಕೆಮಾಡದೆ, ನೇರವಾಗಿ ಈ ಹೆಸರಿನಲ್ಲಿ ಸೇರುತ್ತಾರೆ: {name}. ಇದು ಒಮ್ಮೆ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತದೆ.',
  members_personalMessageBillOne: 'ಈ ಲಿಂಕ್ ತೆರೆಯುವವರು ಪಟ್ಟಿಯಿಂದ ಆಯ್ಕೆಮಾಡದೆ, ನೇರವಾಗಿ ಈ ಹೆಸರಿನಲ್ಲಿ ಸೇರುತ್ತಾರೆ: {name}. ಇಲ್ಲಿಯವರೆಗೆ ಸೇರಿಸಿದ ಖರ್ಚಿನಲ್ಲಿ ತಮ್ಮ ಪಾಲನ್ನೂ ತಕ್ಷಣ ನೋಡುತ್ತಾರೆ: {amount}. ಇದು ಒಮ್ಮೆ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತದೆ.',
