  profile_eraseAndSignOut: 'ಪ್ರೊಫೈಲ್ ಅಳಿಸಿ ಮತ್ತು ಸೈನ್ ಔಟ್ ಮಾಡಿ',
  profile_signOutTitle: 'ಸೈನ್ ಔಟ್ ಮಾಡಬೇಕೆ?',
  profile_signOutBody: 'ಎಲ್ಲವೂ ನಿಮ್ಮ {provider} ಖಾತೆಯೊಂದಿಗೆ ಸಿಂಕ್ ಆಗಿದೆ. ನೀವು ಸೈನ್ ಔಟ್ ಮಾಡಿದಾಗ, ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿರುವ ಪ್ರತಿಯನ್ನು ನಾವು ಅಳಿಸುತ್ತೇವೆ. ನೀವು ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಿದಾಗ ನಿಮ್ಮ ಗುಂಪುಗಳು ಮರಳಿ ಬರುತ್ತವೆ.',
  profile_signOutPendingTitleOne: '{count} ಬದಲಾವಣೆ ಇನ್ನೂ ಅಪ್‌ಲೋಡ್ ಆಗಿಲ್ಲ',
  profile_signOutPendingTitleOther: '{count} ಬದಲಾವಣೆಗಳು ಇನ್ನೂ ಅಪ್‌ಲೋಡ್ ಆಗಿಲ್ಲ',
  profile_signOutPendingBody: 'ಸಿಂಕ್ ಮುಗಿಯುವವರೆಗೆ ನಿಮ್ಮ ಡೇಟಾ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲೇ ಇರುತ್ತದೆ. ಎಲ್ಲವೂ ಅಪ್‌ಲೋಡ್ ಆದ ನಂತರ, ನಾವು ಸೈನ್ ಔಟ್ ಮಾಡಿ ಸ್ಥಳೀಯ ಪ್ರತಿಯನ್ನು ಅಳಿಸುತ್ತೇವೆ.',
  profile_signOutPendingBodyOffline: 'ನೀವು ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿದ್ದೀರಿ. ಸಿಂಕ್ ಮುಗಿಯುವವರೆಗೆ ನಿಮ್ಮ ಡೇಟಾ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲೇ ಇರುತ್ತದೆ. ಎಲ್ಲವೂ ಅಪ್‌ಲೋಡ್ ಆದ ನಂತರ, ನಾವು ಸೈನ್ ಔಟ್ ಮಾಡಿ ಸ್ಥಳೀಯ ಪ್ರತಿಯನ್ನು ಅಳಿಸುತ್ತೇವೆ.',
  profile_signOutWhenSynced: 'ಸಿಂಕ್ ಆದ ನಂತರ ಸೈನ್ ಔಟ್ ಮಾಡಿ',
  profile_signOutNow: 'ಈಗಲೇ ಸೈನ್ ಔಟ್ ಮಾಡಿ ಮತ್ತು ಬದಲಾವಣೆಗಳನ್ನು ಕಳೆದುಕೊಳ್ಳಿ',
  profile_signOutFailed: 'ಸೈನ್ ಔಟ್ ಮಾಡಲು ಆಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  profile_eraseTitle: 'ಈ ಬ್ರೌಸರ್‌ನಿಂದ ಪ್ರೊಫೈಲ್ ಅಳಿಸಬೇಕೆ?',
  profile_eraseBody: 'ನಿಮ್ಮ ಖಾತೆಗೆ Google ಅಥವಾ Apple ಸೈನ್ ಇನ್ ಇಲ್ಲ. ನೀವು ಸೈನ್ ಔಟ್ ಮಾಡಿದಾಗ, ಈ ಬ್ರೌಸರ್‌ನ ಪ್ರತಿಯನ್ನು ನಾವು ಅಳಿಸುತ್ತೇವೆ. ಮರಳಿ ಬರಲು, ನಿಮಗೆ ರಿಕವರಿ ಕೋಡ್ ಬೇಕು. 30 ದಿನ ಬಳಸದಿದ್ದರೆ, ಖಾತೆ ಅಳಿಸಲ್ಪಡುತ್ತದೆ ಮತ್ತು ಕೋಡ್ ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ.',
  profile_eraseBodyNoCode: 'ನೀವು ಖಾತೆ ಇಲ್ಲದೆ ಬಳಸುತ್ತಿದ್ದೀರಿ ಮತ್ತು ಇನ್ನೂ ಸಿಂಕ್ ಮಾಡಿಲ್ಲ, ಹಾಗಾಗಿ ರಿಕವರಿ ಕೋಡ್ ಇಲ್ಲ. ನೀವು ಹೊರಹೋದಾಗ, ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಶಾಶ್ವತವಾಗಿ ಹೋಗುತ್ತದೆ.',
  profile_eraseCodeSaved: 'ನಾನು ಕೋಡ್ ಅನ್ನು ಸುರಕ್ಷಿತ ಸ್ಥಳದಲ್ಲಿ ಇಟ್ಟಿದ್ದೇನೆ',
