  editGroup_simplifyPendingOn: 'ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಆನ್ · ಅಪ್‌ಲೋಡ್ ಆಗಲು ಕಾಯುತ್ತಿದೆ',
