  editGroup_simplifyUnavailableToast: '3 ಕ್ಕಿಂತ ಕಡಿಮೆ ಜನರಿದ್ದರೆ ಸಾಲಗಳನ್ನು ಸರಳಗೊಳಿಸಿ ಲಭ್ಯವಿಲ್ಲ. ಗುಂಪಿನಲ್ಲಿ ಕನಿಷ್ಠ 3 ಜನರಿದ್ದಾಗ ಇದು ಲಭ್ಯವಾಗುತ್ತದೆ.',
  editGroup_simplifyOfflineNote: 'ಇಂಟರ್ನೆಟ್ ಇಲ್ಲ: ಸೂಚಿಸಿದ ಪಾವತಿಗಳು ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಈಗಾಗಲೇ ಬದಲಾಗಿವೆ. ಮತ್ತೆ ಸಂಪರ್ಕಗೊಂಡಾಗ ಗುಂಪು ಇದನ್ನು ನೋಡುತ್ತದೆ.',
