  simplifyConfirm_bodyOn: 'ಎಲ್ಲರೂ ಅದೇ ಒಟ್ಟು ಮೊತ್ತವನ್ನು ಪಾವತಿಸುತ್ತಾರೆ ಅಥವಾ ಪಡೆಯುತ್ತಾರೆ. ಯಾರು ಯಾರಿಗೆ ಪಾವತಿಸುತ್ತಾರೆ ಎಂಬುದು ಮಾತ್ರ ಬದಲಾಗುತ್ತದೆ.',
  simplifyConfirm_bodyOff: 'ಪಾವತಿಗಳು ಮತ್ತೆ ಪ್ರತಿ ಖರ್ಚನ್ನು ಹಂಚಿದವರ ನಡುವೆಯೇ ಇರುತ್ತವೆ. ಒಟ್ಟು ಮೊತ್ತಗಳು ಬದಲಾಗುವುದಿಲ್ಲ.',
