  simplifyConfirm_footOn: 'ಎಲ್ಲರೂ ಇದನ್ನು ಚಟುವಟಿಕೆಯಲ್ಲಿ ನೋಡುತ್ತಾರೆ. ಈಗ ಬೇರೊಬ್ಬರಿಗೆ ಪಾವತಿಸುವವರು ಅಥವಾ ಬೇರೊಬ್ಬರಿಂದ ಪಡೆಯುವವರು ನೋಟಿಫಿಕೇಶನ್ ಪಡೆಯುತ್ತಾರೆ. ಯಾವಾಗ ಬೇಕಾದರೂ ಇದನ್ನು ಆಫ್ ಮಾಡಬಹುದು.',
