  simplifyConflict_activity: 'ಚಟುವಟಿಕೆಯಲ್ಲಿ ನೋಡಿ',
  simplifyInfo_intro: 'ಗುಂಪಿನಲ್ಲಿ, ಪ್ರತಿ ಖರ್ಚು ಇಬ್ಬರ ನಡುವೆ ಸಾಲಗಳನ್ನು ಸೃಷ್ಟಿಸುತ್ತದೆ. ಕಾಲಕ್ರಮೇಣ, ಹಣ ಸುತ್ತುತ್ತಾ ಹೋಗುತ್ತದೆ. ಸರಳಗೊಳಿಸುವಿಕೆ ಆ ಸಾಲಗಳನ್ನು ಸೇರಿಸಿ ಕಡಿಮೆ ಪಾವತಿಗಳನ್ನು ಸೂಚಿಸುತ್ತದೆ.',
