  simplifyInfo_afterLabel: 'ಸರಳಗೊಳಿಸಿದ ನಂತರ: ಕಾರ್ಲಾ ನೇರವಾಗಿ ಬ್ರೂನೋಗೆ {amount} ಪಾವತಿಸುತ್ತಾರೆ. ಎಲಿಸಾ ಏನೂ ಪಾವತಿಸುವುದಿಲ್ಲ. 1 ಪಾವತಿ.',
  simplify_youCapital: 'ನೀವು',
  simplifyInfo_exampleResult: 'ಸರಳಗೊಳಿಸಿದಾಗ, ಕಾರ್ಲಾ ನೇರವಾಗಿ ಬ್ರೂನೋಗೆ {amount} ಪಾವತಿಸುತ್ತಾರೆ, ಮತ್ತು ಎಲಿಸಾ ಏನೂ ಪಾವತಿಸುವುದಿಲ್ಲ.',
