  simplifyInfo_strangerTitle: 'ನೀವು ಎಂದೂ ಖರ್ಚು ಹಂಚಿಕೊಳ್ಳದ ಯಾರಿಗಾದರೂ ಕೊಡಬೇಕಾಗಬಹುದು',
  simplifyInfo_strangerText: 'ಹಾಗಾದಾಗ, ಗುಂಪಿನ ಬ್ಯಾಲೆನ್ಸ್‌ನಲ್ಲಿರುವ ‘ಸರಳಗೊಳಿಸಿದ ಸಾಲಗಳು’ ಲೇಬಲ್ ನಿಮಗೆ ತಿಳಿಸುತ್ತದೆ.',
  simplifyInfo_anyoneTitle: 'ಯಾರು ಬೇಕಾದರೂ ಇದನ್ನು ಆನ್ ಅಥವಾ ಆಫ್ ಮಾಡಬಹುದು',
  simplifyInfo_anyoneText: 'ಗುಂಪನ್ನು ಎಡಿಟ್ ಮಾಡಿ ಎಂಬಲ್ಲಿ. ಯಾರು ಬದಲಾಯಿಸಿದರು ಎಂದು ಚಟುವಟಿಕೆ ತೋರಿಸುತ್ತದೆ, ಮತ್ತು ಈಗ ಬೇರೊಬ್ಬರಿಗೆ ಪಾವತಿಸುವವರು ಅಥವಾ ಬೇರೊಬ್ಬರಿಂದ ಪಡೆಯುವವರು ನೋಟಿಫಿಕೇಶನ್ ಪಡೆಯುತ್ತಾರೆ.',
  simplifyInfo_offTitle: 'ಆಫ್ ಮಾಡಿದರೆ ಹಿಂದಿನಂತಾಗುತ್ತದೆ',
  simplifyInfo_offText: 'ಪಾವತಿಗಳು ಮತ್ತೆ ಪ್ರತಿ ಖರ್ಚನ್ನು ಹಂಚಿದವರ ನಡುವೆಯೇ ಇರುತ್ತವೆ. ಯಾವುದೇ ಖರ್ಚು ಅಥವಾ ದಾಖಲಿಸಿದ ಪಾವತಿ ಬದಲಾಗುವುದಿಲ್ಲ.',
  balances_simplifiedBody: '{before} ಬದಲಿಗೆ {count} ಪಾವತಿಗಳು. ನೀವು ಎಂದೂ ಖರ್ಚು ಹಂಚಿಕೊಳ್ಳದ ಯಾರಿಗಾದರೂ ಪಾವತಿಸಬೇಕಾಗಬಹುದು ಅಥವಾ ಅವರಿಂದ ಪಡೆಯಬಹುದು.',
  balances_simplifiedMinimal: 'ಈಗಾಗಲೇ ಅತಿ ಕಡಿಮೆ ಪಾವತಿಗಳು. ಮುಂದಿನ ಖರ್ಚುಗಳು ಸರಳಗೊಂಡು ಬರುತ್ತವೆ.',
  balances_simplifiedNote: 'ಸರಳಗೊಳಿಸಿದ ಸಾಲಗಳೊಂದಿಗೆ, ಆ್ಯಪ್ ಅತಿ ಕಡಿಮೆ ಪಾವತಿಗಳನ್ನು ಸೂಚಿಸುತ್ತದೆ. “ಹಣ ಬಂತು” ಮತ್ತು “ಈಗಾಗಲೇ ಪಾವತಿಸಿದೆ” ಆ್ಯಪ್‌ನ ಹೊರಗೆ ಮಾಡಿದ ಪಾವತಿಯನ್ನು (Pix, ನಗದು, ವರ್ಗಾವಣೆ) ದಾಖಲಿಸುತ್ತವೆ.',
  registerPayment_simplifiedNewPair: 'ಸರಳಗೊಳಿಸಿದ ಸಾಲ: {payer} ಪಾವತಿಸುತ್ತಾರೆ, ಪಡೆಯುವವರು: {receiver}; ಮೊದಲು ಇದನ್ನು ಪಡೆಯಬೇಕಿದ್ದವರು: {insteadOf}.',
